        .spinner { width: 40px; height: 40px; border: 2px solid rgba(255, 255, 255, 0.05); border-top: 2px solid var(--primary); border-right: 2px solid var(--secondary); border-radius: 50%; animation: spin 0.8s linear infinite; margin: 0 auto 20px auto; box-shadow: 0 0 20px rgba(255,138,179,0.2), inset 0 0 20px rgba(0,229,255,0.1); }
