        #info-btn { width: 44px; height: 44px; border-radius: 50%; border: 1px solid rgba(255, 138, 179, 0.3); background: rgba(13, 6, 20, 0.6); color: var(--primary); cursor: pointer; pointer-events: auto; display: flex; justify-content: center; align-items: center; backdrop-filter: blur(10px); transition: all 0.3s ease; animation: float 3s ease-in-out infinite; }
        #info-btn:hover, #info-btn.active { background: rgba(255, 138, 179, 0.15); border-color: rgba(255, 138, 179, 0.6); transform: scale(1.1); box-shadow: 0 0 25px rgba(255,138,179,0.3); }

        /* Popup bubble hint */
        #info-bubble {
            position: absolute; bottom: 55px; left: 0;
            background: rgba(15, 8, 25, 0.85); border: 1px solid rgba(255, 138, 179, 0.3);
            border-radius: 12px; padding: 10px 16px; pointer-events: auto; cursor: pointer;
            backdrop-filter: blur(15px); white-space: nowrap;
