        }
        #info-bubble .bubble-icon { margin-right: 8px; }
        #info-bubble.hidden { opacity: 0; transform: translateY(5px); pointer-events: none; }
        @keyframes bubblePulse { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-4px); } }
        #info-panel { background: rgba(10, 5, 15, 0.75); border: 1px solid rgba(255, 255, 255, 0.08); padding: 30px; border-radius: 20px; backdrop-filter: blur(30px); opacity: 0; transform: translateX(-15px) translateY(10px); pointer-events: none; transition: all 0.5s cubic-bezier(0.16, 1, 0.3, 1); box-shadow: 0 20px 50px rgba(0,0,0,0.8); }
