        .detail-hero::after { content: ''; position: absolute; inset: 0; background: linear-gradient(to top, rgba(10, 5, 15, 1) 0%, rgba(10, 5, 15, 0.2) 100%); z-index: 1; }

        .detail-content-wrap { padding: 40px 80px 80px 80px; position: relative; z-index: 2; margin-top: -80px; }
        #detail-modal h1 { color: #fff; font-size: 54px; font-weight: 600; margin: 0 0 10px 0; letter-spacing: -0.5px; line-height: 1.1; background: linear-gradient(135deg, #ffffff, var(--primary)); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
        .subtitle { font-family: 'JetBrains Mono', monospace; font-size: 15px; color: var(--primary); margin-bottom: 40px; letter-spacing: 1.5px; text-transform: uppercase; text-shadow: 0 0 20px rgba(255,138,179,0.3); }
