        /* === DISCLAIMER MODAL === */
        #disclaimer-overlay {
            position: fixed; inset: 0; z-index: 9999; background: rgba(5, 2, 10, 0.95);
            display: flex; justify-content: center; align-items: center;
            backdrop-filter: blur(20px); transition: opacity 0.6s ease;
        }
        #disclaimer-overlay.hidden { opacity: 0; pointer-events: none; }
        #disclaimer-box {
