        #disclaimer-box .disclaimer-icon { font-size: 48px; margin-bottom: 20px; }
        #disclaimer-box h2 { font-size: 24px; font-weight: 600; margin-bottom: 16px; color: #fff; letter-spacing: 0.5px; }
        #disclaimer-box p { font-size: 15px; color: var(--text-muted); line-height: 1.8; margin-bottom: 30px; font-weight: 300; }
        #disclaimer-box .highlight { color: var(--primary); font-weight: 500; }
        #disclaimer-accept {
            background: linear-gradient(135deg, var(--primary), #ff5e99); color: #fff;
            border: none; padding: 14px 40px; border-radius: 50px; font-size: 15px;
            font-family: 'Outfit', sans-serif; font-weight: 500; cursor: pointer;
            transition: all 0.3s ease; letter-spacing: 0.5px;
