        #lang-toggle span.active-lang { color: var(--primary); }
        .toggle-switch {
            width: 40px; height: 20px; background: rgba(255,255,255,0.1);
            border-radius: 10px; position: relative; cursor: pointer;
            border: 1px solid rgba(255,255,255,0.15); transition: all 0.3s;
        }
        .toggle-switch::after {
            content: ''; position: absolute; top: 2px; left: 2px;
            width: 14px; height: 14px; border-radius: 50%;
            background: var(--primary); transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
