<body>

    <!-- PRIVACY DISCLAIMER -->
    <div id="disclaimer-overlay">
        <div id="disclaimer-box">
            <div class="disclaimer-icon">🔒</div>
            <h2>Camera Permission Required</h2>
            <p>This portfolio uses <span class="highlight">AI hand gesture recognition</span> for navigation. Your camera feed is processed <span class="highlight">entirely in your browser</span> using MediaPipe.<br><br>
            <strong style="color:#fff;">No video, images, or personal data is recorded, stored, or transmitted to any server.</strong><br><br>
