    <script type="module">
        import * as THREE from 'three';
        import { CSS3DRenderer, CSS3DObject } from 'three/addons/renderers/CSS3DRenderer.js';

        document.getElementById('info-btn').addEventListener('click', () => {
            const panel = document.getElementById('info-panel');
            const bubble = document.getElementById('info-bubble');
            document.getElementById('info-btn').classList.toggle('active');
            panel.classList.toggle('active');
            // Show bubble when panel is closed, hide when open
            if (panel.classList.contains('active')) {
                bubble.classList.add('hidden');
            } else {
                bubble.classList.remove('hidden');
            }
        });

        // Clicking the bubble opens the panel
        document.getElementById('info-bubble').addEventListener('click', () => {
            document.getElementById('info-btn').classList.add('active');
            document.getElementById('info-panel').classList.add('active');
            document.getElementById('info-bubble').classList.add('hidden');
        });

        // === DISCLAIMER HANDLER ===
        document.getElementById('disclaimer-accept').addEventListener('click', () => {
            const overlay = document.getElementById('disclaimer-overlay');
            overlay.classList.add('hidden');
            setTimeout(() => { overlay.style.display = 'none'; }, 600);
        });

        // === LANGUAGE TOGGLE ===
        let currentLang = 'en';
        document.getElementById('lang-switch').addEventListener('click', () => {
            const toggle = document.getElementById('lang-switch');
            toggle.classList.toggle('cn');
            currentLang = currentLang === 'en' ? 'cn' : 'en';
            document.getElementById('lang-en').classList.toggle('active-lang', currentLang === 'en');
            document.getElementById('lang-cn').classList.toggle('active-lang', currentLang === 'cn');
            document.querySelectorAll('.info-desc[data-en]').forEach(el => {
                el.textContent = currentLang === 'en' ? el.dataset.en : el.dataset.cn;
            });
        });

        // 辅助生成 Tech Stack 图标的 HTML
        const techIcon = (name, url) => `<div class="tech-icon-wrap"><img src="${url}" alt="${name}">${name}</div>`;

        // ==========================================
        // 1. 注入了高清配图和 Logo 的数据源
        // ==========================================
        const portfolioData = [
            { 
                id: 0, indexStr: '01', title: 'PROFILE', brief: 'Jens Liew<br>Cloud & Software Engineer<br>Full-Stack Developer', 
                cover: './images/profile.png',
                details: `
