    });
  }

  function enterDetail() {
    isDetailMode = true;
    gsap.to(camera.position, { z: 620, duration: 0.6, ease: "power2.out" });
  }

  function exitDetail() {
    isDetailMode = false;
    gsap.to(camera.position, { z: 1500, duration: 0.7, ease: "power2.out" });
  }

  function destroy() {
    window.removeEventListener("resize", handleResize);
    glRenderer.dispose();
  }

  return {
    syncActiveRecord,
    enterDetail,
    exitDetail,
    destroy
  };
}
